-- Create "customers" table
CREATE TABLE "customers" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "email" character varying(320) NOT NULL, "name" character varying(200) NULL, "plan" text NOT NULL DEFAULT 'free', "created_at" timestamptz NOT NULL DEFAULT now(), PRIMARY KEY ("id"), CONSTRAINT "customers_plan_check" CHECK (plan = ANY (ARRAY['free'::text, 'pro'::text])));
